				seeds = append(seeds, registerCreated(t, router, denyBody, 2, false))
			} else {
				seeds = append(seeds, registerCreated(t, router, denyBody, 1, false))
				seeds = append(seeds, registerCreated(t, router, egressBody, 2, false))
